const catalog = $input.all().map(i => i.json);

const aiResponse = $('AI Read Request').first().json;
const customer = $('Filter Message').first().json;

// Extract Gemini response
let data;

try {
  const raw =
    aiResponse.candidates?.[0]?.content?.parts
      ?.map(p => p.text || '').join('')
    ?? aiResponse.output
    ?? aiResponse.text
    ?? aiResponse;

  data = typeof raw === 'string'
    ? JSON.parse(raw.replace(/```json|```/gi, '').trim())
    : raw;

  if (!data || typeof data !== 'object') {
    throw new Error('Invalid AI response');
  }

} catch (error) {
  data = {
    is_prescription: false,
    readable: false,
    medicines: []
  };
}

// Normalize data
const normalize = value =>
  String(value ?? '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');

const strengthPattern =
  /\d+(?:[.,]\d+)?\s*(?:mg|mcg|g|ml)\b/i;

const medicineName = value =>
  normalize(value)
    .replace(strengthPattern, '')
    .trim();

const strengthValue = value =>
  normalize(value).replace(/\s+/g, '');

const medicines = Array.isArray(data.medicines)
  ? data.medicines
  : [];

// Separate medicines by route
const autoMedicines = [];
const pharmacistMedicines = [];

const pharmacistIssues = [];
const unavailableIssues = [];

// Add medicine without duplicate SKU
function addMedicine(list, product, qty) {
  const sku = String(product.sku).trim();

  const existing = list.find(
    m => String(m.sku).trim() === sku
  );

  if (existing) {
    existing.qty += qty;
    existing.total_egp =
      existing.qty * existing.price_egp;
    return;
  }

  const price = Number(product.price_egp);

  list.push({
    sku,
    name: product.name,
    strength: product.strength,
    qty,
    price_egp: price,
    total_egp: price * qty,
    stock: Number(product.stock),
    controlled: product.controlled
  });
}

// Match medicines
for (const med of medicines) {

  const name = medicineName(med.name);

  const strength = strengthValue(
    med.strength ||
    String(med.name ?? '')
      .match(strengthPattern)?.[0] ||
    ''
  );

  const qty = Number(med.qty ?? 1);

  if (
    !name ||
    name === '?' ||
    !strength ||
    !Number.isInteger(qty) ||
    qty <= 0
  ) {
    pharmacistIssues.push({
      name: med.name || 'Unknown medicine',
      reason: 'incomplete_details'
    });
    continue;
  }

  const products = catalog.filter(p =>
    medicineName(p.name) === name &&
    strengthValue(p.strength) === strength
  );

  if (products.length !== 1) {
    const issue = {
      name: med.name,
      reason: products.length === 0
        ? 'not_found'
        : 'ambiguous_match'
    };

    if (products.length > 1) {
      pharmacistIssues.push(issue);
    } else {
      unavailableIssues.push(issue);
    }

    continue;
  }

  const product = products[0];
  const stock = Number(product.stock);
  const price = Number(product.price_egp);

  if (
    !Number.isInteger(stock) ||
    stock < 0 ||
    !Number.isFinite(price) ||
    price < 0
  ) {
    pharmacistIssues.push({
      name: med.name,
      reason: 'invalid_catalog_data'
    });
    continue;
  }

  const controlled = normalize(product.controlled);

  const requiresPrescription =
    normalize(product.requires_prescription || 'no') === 'yes';

  const needsPharmacist =
    controlled !== 'no' ||
    requiresPrescription ||
    data.is_prescription === true ||
    data.readable === false;

  if (needsPharmacist) {
    addMedicine(pharmacistMedicines, product, qty);
  } else {
    addMedicine(autoMedicines, product, qty);
  }
}

// Check total requested quantity per SKU
function checkStock(list) {
  for (let i = list.length - 1; i >= 0; i--) {
    const med = list[i];

    if (med.qty > med.stock) {
      unavailableIssues.push({
        name: med.name,
        reason: 'insufficient_stock'
      });

      list.splice(i, 1);
    }
  }
}

checkStock(autoMedicines);
checkStock(pharmacistMedicines);

// Generate a common request ID
const now = $now.setZone('Africa/Cairo');

const baseId =
  'R-' +
  now.toFormat('yyMMddHHmmss') +
  '-' +
  Math.floor(1000 + Math.random() * 9000);

const results = [];

// Build one output for each route
function addRoute(route, matched, issues, suffix) {

  if (!matched.length && !issues.length) {
    return;
  }

  results.push({
    json: {
      customer_id: customer.customer_id,
      customer_name: customer.customer_name,
      wa_phone_id: customer.wa_phone_id,

      res_id: baseId + '-' + suffix,
      request_group: baseId,

      route,

      nothing: route === 'nothing_found'
        ? 'true' : 'false',

      "needs pharmacist": route === 'pharmacist'
        ? 'true' : 'false',

      auto_reservation: route === 'auto_reservation'
        ? 'true' : 'false',

      is_prescription: data.is_prescription === true,
      readable: data.readable === true,

      matched,
      issues,

      total_egp: matched.reduce(
        (sum, m) => sum + m.total_egp,
        0
      )
    }
  });
}

// Automatic reservation group
addRoute(
  'auto_reservation',
  autoMedicines,
  [],
  'A'
);

// Pharmacist review group
addRoute(
  'pharmacist',
  pharmacistMedicines,
  pharmacistIssues,
  'P'
);

// Unavailable medicines
addRoute(
  'nothing_found',
  [],
  unavailableIssues,
  'N'
);

// Handle empty or unreadable messages
if (results.length === 0) {
  addRoute(
    customer.type === 'image'
      ? 'pharmacist'
      : 'nothing_found',
    [],
    [{
      name: 'Unknown request',
      reason: 'no_medicines_identified'
    }],
    'X'
  );
}

return results;

