const orders = $input.all().map(i => i.json);

if (!orders.length) {
  throw new Error('No reservation data received');
}

const catalog = $('Read Catalog')
  .all()
  .map(i => i.json);

const requested = new Map();

const reservationId = String(
  orders[0].res_id || ''
).trim();

if (!reservationId) {
  throw new Error('Missing reservation ID');
}

// Process only automatically reserved medicines
for (const order of orders) {

  const status = String(
    order.status || ''
  ).trim().toLowerCase();

  const route = String(
    order.route || ''
  ).trim().toLowerCase();

  if (status !== 'reserved') {
    throw new Error(
      'Medicine is not automatically reserved'
    );
  }

  // Route may be missing after Google Sheets
  if (route && route !== 'auto_reservation') {
    throw new Error(
      'Invalid automatic reservation route'
    );
  }

  if (String(order.res_id || '').trim() !== reservationId) {
    throw new Error('Mixed reservation IDs');
  }

  const sku = String(order.sku || '').trim();
  const qty = Number(order.qty);

  if (
    !sku ||
    !Number.isInteger(qty) ||
    qty <= 0
  ) {
    throw new Error(
      'Invalid medicine or quantity'
    );
  }

  requested.set(
    sku,
    (requested.get(sku) || 0) + qty
  );
}

// Calculate new stock
const results = [];

for (const [sku, qty] of requested) {

  const matches = catalog.filter(p =>
    String(p.sku || '').trim() === sku
  );

  if (matches.length !== 1) {
    throw new Error(
      'Catalog item missing or duplicated: ' + sku
    );
  }

  const product = matches[0];

  const controlled = String(
    product.controlled || ''
  ).trim().toLowerCase();

  if (controlled !== 'no') {
    throw new Error(
      'Pharmacist approval required: ' + sku
    );
  }

  const requiresPrescription = String(
    product.requires_prescription || 'no'
  ).trim().toLowerCase();

  if (
    ['yes', 'true', '1'].includes(requiresPrescription)
  ) {
    throw new Error(
      'Prescription review required: ' + sku
    );
  }

  const stock = Number(product.stock);

  if (
    !Number.isInteger(stock) ||
    stock < qty
  ) {
    throw new Error(
      'Insufficient stock: ' + sku
    );
  }

  results.push({
    json: {
      res_id: reservationId,
      sku,
      qty,
      stock_before: stock,
      stock_after: stock - qty
    }
  });
}

return results;

