{{ (() => {
  const groups = $('Match Catalog')
    .all()
    .map(i => i.json);

  const auto = groups.find(
    g => g.route === 'auto_reservation'
  );

  if (!auto || !auto.matched?.length) {
    throw new Error('No auto reservation found');
  }

  const pharma = groups.find(g =>
    g.route === 'pharmacist' &&
    g.request_group === auto.request_group
  );

  // Verify automatic stock updates
  const expected = $('Take Stock Now')
    .all()
    .map(i => i.json);

  const updated = $('Update Catalog')
    .all()
    .map(i => i.json);

  for (const med of auto.matched) {
    const stockRow = expected.find(r =>
      String(r.sku) === String(med.sku)
    );

    if (!stockRow) {
      throw new Error(
        'Missing stock calculation: ' + med.sku
      );
    }

    const savedRow = updated.find(r =>
      String(r.sku) === String(med.sku) &&
      Number(r.stock) === Number(stockRow.stock_after)
    );

    if (!savedRow) {
      throw new Error(
        'Stock update not verified: ' + med.sku
      );
    }
  }

  // Automatic medicines
  const autoList = auto.matched.map((med, i) =>
    [
      `${i + 1}. ${med.name} - ${med.strength}`,
      `📦 الكمية: ${med.qty}`,
      `💰 السعر: ${med.total_egp} جنيه`
    ].join('\n')
  ).join('\n\n');

  // Medicines awaiting pharmacist approval
  const pharmaItems = pharma
    ? [
        ...(pharma.matched || []),
        ...(pharma.issues || []).map(issue => ({
          name: issue.name || 'دواء غير واضح',
          strength: '',
          qty: 'تحتاج مراجعة'
        }))
      ]
    : [];

  const pharmaList = pharmaItems.map((med, i) =>
    [
      `${i + 1}. ${med.name}${med.strength ? ' - ' + med.strength : ''}`,
      `📦 الكمية: ${med.qty || 'تحتاج مراجعة'}`
    ].join('\n')
  ).join('\n\n');

  // Calculate confirmed total only
  const total = auto.matched.reduce(
    (sum, med) =>
      sum + Number(med.total_egp || 0),
    0
  );

  // Get expiration date for Auto reservation
  const rows = $('One Row per Medicine')
    .all()
    .map(i => i.json);

  const autoRow = rows.find(r =>
    String(r.res_id) === String(auto.res_id)
  );

  if (!autoRow?.expires_at) {
    throw new Error('Missing reservation expiry date');
  }

  const expiryDate = String(autoRow.expires_at)
    .split(' ')[0];

  // Build final WhatsApp message
  return [
    `أهلاً ${auto.customer_name || 'بحضرتك'} 👋`,
    '💊 تفاصيل طلبك:',
    '',
    '✅ تم حجز الأدوية التالية:',
    autoList,

    ...(pharma ? [
      '',
      '⏳ الأدوية التي تحتاج موافقة الصيدلي:',
      pharmaList || 'طلب يحتاج مراجعة الصيدلي'
    ] : []),

    '',
    '━━━━━━━━━━━━━━━━',
    `💰 إجمالي الأدوية المحجوزة: ${total} جنيه`,
    '━━━━━━━━━━━━━━━━',

    `🔖 رقم الحجز: ${auto.res_id}`,

    ...(pharma ? [
      `🔖 رقم طلب المراجعة: ${pharma.res_id}`
    ] : []),

    `📅 الحجز متاح حتى: ${expiryDate}`,

    ...(pharma ? [
      'سيتم إبلاغك بنتيجة مراجعة الصيدلي.'
    ] : []),

    'يرجى استلام الأدوية المحجوزة قبل انتهاء مدة الحجز.',
    'شكراً لتعاملك مع Dawa Pharmacy ❤️'
  ].join('\n');

})() }}

