const buf = await this.helpers.getBinaryDataBuffer(0, 'data');

return [{
  json: {
    ...$('Filter Message').first().json,
    b64: buf.toString('base64'),
    mime: $input.first().binary.data.mimeType || 'image/jpeg',
    prompt: 'This is a photo of an Egyptian prescription or medicine box. Return JSON only: {"is_prescription": true|false, "readable": true|false, "medicines": [{"name": "", "strength": "", "qty": 1}]}. qty = boxes requested, default 1. Never guess an unreadable name: put it as "?".'
  }
}];

// Keep customer messages only. Text and photos (prescriptions) are both
// accepted.
const m = $json.messages?.[0]; if (!m) return [];

return [{
  json: {
    customer_id: m.from,
    customer_name: $json.contacts?.[0]?.profile?.name || '',
    wa_phone_id: $json.metadata.phone_number_id,
    type: m.type,
    text: m.text?.body || m.image?.caption || '',
    media_id: m.image?.id || ''
  }
}];

const orders = $input.all().map(item => item.json);

const results = [];

for (const order of orders) {

  const route = String(order.route || '').trim();

  // Accept only Auto or Pharmacist routes
  if (!['auto_reservation', 'pharmacist'].includes(route)) {
    throw new Error('Invalid reservation route: ' + route);
  }

  const medicines = Array.isArray(order.matched)
    ? order.matched
    : [];

  const issues = Array.isArray(order.issues)
    ? order.issues.filter(
        issue => issue.reason !== 'pharmacist_required'
      )
    : [];

  const needsPharmacist = route === 'pharmacist';

  // Keep reservation ID generated by Match Catalog
  const res_id = String(order.res_id || '').trim();

  if (!res_id) {
    throw new Error('Missing reservation ID');
  }

  if (!order.customer_id || !order.wa_phone_id) {
    throw new Error('Missing customer information');
  }

  // Validate automatic reservations
  if (!needsPharmacist && (
    medicines.length === 0 || issues.length > 0
  )) {
    throw new Error('Invalid automatic reservation');
  }

  // Expiration after 30 minutes for Auto
  const expires_at = needsPharmacist
    ? ''
    : new Date(Date.now() + 30 * 60 * 1000)
        .toLocaleString('sv-SE', {
          timeZone: 'Africa/Cairo'
        });

  // Reservation status
  const status = needsPharmacist
    ? 'pending_pharmacist'
    : 'reserved';

  const pharmacist = needsPharmacist
    ? 'Pending Pharmacist'
    : 'Not Assigned';

  // Shared order information
  const common = {
    res_id,
    request_group: order.request_group || '',
    customer_id: String(order.customer_id),
    wa_phone_id: String(order.wa_phone_id),
    customer_name: order.customer_name || '',
    route,
    status,
    expires_at,
    pharmacist
  };

  // Create one row per matched medicine
  for (const med of medicines) {

    const sku = String(med.sku || '').trim();
    const qty = Number(med.qty);
    const price = Number(med.price_egp);
    const total = Number(med.total_egp);
    const stock = Number(med.stock);

    if (
      !sku ||
      !Number.isInteger(qty) ||
      qty <= 0 ||
      !Number.isFinite(price) ||
      price < 0 ||
      !Number.isFinite(total) ||
      total !== qty * price ||
      !Number.isInteger(stock) ||
      stock < qty
    ) {
      throw new Error(
        'Invalid medicine data: ' + (med.name || sku)
      );
    }

    if (
      !needsPharmacist &&
      String(med.controlled || '').trim().toLowerCase() !== 'no'
    ) {
      throw new Error(
        'Medicine requires pharmacist review: ' + sku
      );
    }

    results.push({
      json: {
        ...common,
        sku,
        name: med.name,
        strength: med.strength,
        qty,
        price_egp: price,
        total_egp: total,
        note: needsPharmacist
          ? 'Awaiting pharmacist approval'
          : ''
      }
    });
  }

  // Add unresolved medicines for pharmacist review
  if (needsPharmacist) {

    for (const issue of issues) {

      results.push({
        json: {
          ...common,
          sku: '',
          name: issue.name || 'Unknown medicine',
          strength: '',
          qty: '',
          price_egp: '',
          total_egp: '',
          note: 'Review required: ' + issue.reason
        }
      });
    }

    // Handle request with no readable medicines
    if (medicines.length === 0 && issues.length === 0) {

      results.push({
        json: {
          ...common,
          sku: '',
          name: 'Manual review required',
          strength: '',
          qty: '',
          price_egp: '',
          total_egp: '',
          note: 'Prescription requires pharmacist review'
        }
      });
    }
  }
}

return results;

const d = $('Parse Decision').first().json;

// Get reservation lines
const lines = $('Find Pending Lines')
  .all()
  .map(i => i.json)
  .filter(l =>
    String(l.res_id ?? '').trim() ===
    String(d.group ?? '').trim()
  );

// Get current catalog
const catalog = $input.all().map(i => i.json);

// Normalize SKU
const normalizeSku = value =>
  String(value ?? '')
    .trim()
    .toUpperCase();

// Verify pharmacist
const q = $('Telegram Trigger')
  .first().json.callback_query;

const allowedIds = ['YOUR_PRIVATE_ID'];

const pharmacistId = String(q?.from?.id || '');

if (!allowedIds.includes(pharmacistId)) {
  throw new Error('Unauthorized pharmacist');
}

// Validate decision
if (!['approve', 'reject'].includes(d.action)) {
  throw new Error('Invalid pharmacist decision');
}

// Failure response
const fail = message => [{
  json: {
    ...d,
    ok: false,
    approved: false,
    toast: message,
    line_updates: [],
    stock_updates: []
  }
}];

// Validate reservation
if (!lines.length) {
  return fail('Reservation not found');
}

// Verify customer
const normalizePhone = value =>
  String(value ?? '').replace(/\D/g, '');

const customer = normalizePhone(d.customer);

if (
  !customer ||
  lines.some(l =>
    normalizePhone(l.customer_id) !== customer
  )
) {
  return fail('Customer does not match reservation');
}

// Check reservation status
if (lines.some(l =>
  String(l.status ?? '').trim() !==
  'pending_pharmacist'
)) {
  return fail('Reservation already processed');
}

// Validate row numbers
if (lines.some(l =>
  !Number.isInteger(Number(l.row_number)) ||
  Number(l.row_number) < 2
)) {
  return fail('Invalid reservation row number');
}

// Normalize medicine names
const normalizeName = value =>
  String(value ?? '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');

// Find valid reservation lines
const validLines = lines.filter(l =>
  normalizeSku(l.sku) &&
  Number.isInteger(Number(l.qty)) &&
  Number(l.qty) > 0
);

// Detect old duplicate review rows
const legacyDuplicates = lines.filter(l => {

  const note = String(
    l.note ?? l[' note'] ?? ''
  ).trim();

  const missingDetails =
    !normalizeSku(l.sku) &&
    !String(l.qty ?? '').trim();

  const hasMatchingMedicine = validLines.some(v =>
    normalizeName(v.name) ===
    normalizeName(l.name)
  );

  return (
    missingDetails &&
    note === 'Review required: pharmacist_required' &&
    hasMatchingMedicine
  );
});

// Exclude duplicate rows from stock calculation
const activeLines = lines.filter(l =>
  !legacyDuplicates.includes(l)
);

if (!activeLines.length) {
  return fail('No valid reservation medicines');
}

// Determine decision
const approved = d.action === 'approve';

const requested = new Map();
const stockUpdates = [];

// Validate medicine details if approved
if (approved) {

  for (const l of activeLines) {

    const sku = normalizeSku(l.sku);
    const qty = Number(l.qty);

    if (
      !sku ||
      !Number.isInteger(qty) ||
      qty <= 0
    ) {
      return fail('Medicine details need review');
    }

    requested.set(
      sku,
      (requested.get(sku) || 0) + qty
    );
  }

  // Check each medicine in catalog
  for (const [sku, qty] of requested) {

    const products = catalog.filter(p =>
      normalizeSku(p.sku) === sku
    );

    // Detailed diagnostic for missing SKU
    if (products.length !== 1) {

      const catalogSkus = catalog
        .map(p => normalizeSku(p.sku))
        .join(', ');

      return fail(
        'Medicine: ' + sku +
        ' | Matches: ' + products.length +
        ' | Catalog SKUs: ' + catalogSkus
      );
    }

    const product = products[0];

    const currentStock = Number(product.stock);

    if (
      !Number.isInteger(currentStock) ||
      currentStock < 0
    ) {
      return fail(
        'Invalid stock for ' + sku
      );
    }

    if (currentStock < qty) {
      return fail(
        'Not enough stock for ' + sku +
        ' | Available: ' + currentStock +
        ' | Requested: ' + qty
      );
    }

    stockUpdates.push({
      sku: product.sku,
      qty,
      stock_before: currentStock,
      stock_after: currentStock - qty
    });
  }
}

// Cairo date and time
const now = $now.setZone('Africa/Cairo');

const decidedAt =
  now.toFormat('yyyy-MM-dd HH:mm:ss');

const exp = approved
  ? now.plus({ hours: 2 })
      .toFormat('yyyy-MM-dd HH:mm:ss')
  : '';

const status = approved
  ? 'approved'
  : 'rejected';

// Prepare line updates
const lineUpdates = lines.map(l => {

  const isDuplicate =
    legacyDuplicates.includes(l);

  const rowStatus = isDuplicate
    ? 'ignored_duplicate'
    : status;

  return {
    row_number: Number(l.row_number),
    res_id: l.res_id,
    status: rowStatus,
    expires_at: isDuplicate ? '' : exp,
    pharmacist: d.by || pharmacistId,
    note: isDuplicate
      ? 'Duplicate pharmacist review row ignored'
      : rowStatus + ' by ' +
        (d.by || pharmacistId) +
        ' at ' + decidedAt
  };
});

// Final output
return [{
  json: {
    ...d,

    ok: true,
    approved,
    status,

    toast: approved
      ? 'Approval validated'
      : 'Rejection validated',

    res_id: d.group,

    customer_id: activeLines[0].customer_id,
    customer_name: activeLines[0].customer_name,
    wa_phone_id: activeLines[0].wa_phone_id,

    pharmacist_id: pharmacistId,
    pharmacist_name: d.by || pharmacistId,

    decided_at: decidedAt,
    expires_at: exp,

    medicines_count: activeLines.length,
    ignored_duplicates: legacyDuplicates.length,

    line_updates: lineUpdates,
    stock_updates: stockUpdates
  }
}];

