const q = $json.callback_query;

const [, action, group, customer] =
  String(q.data || '').split(':');

if (!group) return [];

return [{
  json: {
    action,
    group,
    customer,
    query_id: q.id,
    chat_id: q.message.chat.id,
    message_id: q.message.message_id,
    original: q.message.text,
    by: q.from.username || q.from.first_name
  }
}];

const d = $('Apply Decision').first().json;

// Validate decision
if (d.ok !== true) {
  throw new Error(
    'Apply Decision failed: ' +
    (d.toast || 'Unknown error')
  );
}

// Get reservation updates
const lines = d.line_updates || [];

if (!Array.isArray(lines) || lines.length === 0) {
  throw new Error('No reservation updates found');
}

// Create one item per reservation line
return lines.map(l => {

  const rowNumber = Number(l.row_number);

  if (
    !Number.isInteger(rowNumber) ||
    rowNumber < 2 ||
    !l.res_id ||
    !l.status
  ) {
    throw new Error(
      'Missing or invalid reservation row data'
    );
  }

  return {
    json: {
      row_number: rowNumber,
      res_id: l.res_id,
      status: l.status,
      expires_at: l.expires_at || '',
      pharmacist: l.pharmacist || '',
      note: l.note || ''
    }
  };
});

const d = $('Apply Decision').first().json;

// Validate approval
if (d.ok !== true || d.approved !== true) {
  throw new Error(
    'Reservation is not approved'
  );
}

// Get stock updates
const rows = d.stock_updates || [];

if (!Array.isArray(rows) || rows.length === 0) {
  throw new Error('No stock updates found');
}

// Create one item per medicine
return rows.map(row => {

  const sku = String(row.sku || '').trim();
  const qty = Number(row.qty);
  const stockBefore = Number(row.stock_before);
  const stockAfter = Number(row.stock_after);

  if (
    !sku ||
    !Number.isInteger(qty) ||
    qty <= 0 ||
    !Number.isInteger(stockBefore) ||
    !Number.isInteger(stockAfter) ||
    stockAfter < 0 ||
    stockBefore - qty !== stockAfter
  ) {
    throw new Error(
      'Invalid stock data for ' + sku
    );
  }

  return {
    json: {
      res_id: d.res_id,
      sku: sku,
      qty: qty,
      stock_before: stockBefore,
      stock_after: stockAfter,
      stock: stockAfter
    }
  };
});
